// Global search + notification helpers. Records come from src/data/modul-index.json,
// generated by `npm run data` from the seed data in the design export.
import data from '../data/modul-index.json';

export const TODAY_ISO = '2026-10-19';
export const modulData = data;

const READ_KEY = 'modul.notifications.read.v1';
export function readSet() { try { return new Set(JSON.parse(localStorage.getItem(READ_KEY) || '[]')); } catch { return new Set(); } }
export function writeSet(set) { try { localStorage.setItem(READ_KEY, JSON.stringify(Array.from(set))); } catch { /* storage blocked */ } }
export const READ_STORAGE_KEY = READ_KEY;

const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const parse = s => { const [y, m, d] = s.split('-').map(Number); return new Date(y, m - 1, d); };
export function relDay(s) {
  const n = Math.round((parse(s) - parse(TODAY_ISO)) / 864e5);
  if (n === 0) return 'Today';
  if (n === -1) return 'Yesterday';
  if (n < 0 && n > -7) return -n + ' days ago';
  const d = parse(s); return d.getDate() + ' ' + MON[d.getMonth()];
}

const norm = s => (s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/ø/g, 'o').replace(/æ/g, 'a').replace(/å/g, 'a');
export function search(items, q) {
  const n = norm(q.trim()); if (!n) return [];
  const words = n.split(/\s+/);
  const out = [];
  items.forEach(it => {
    const t = norm(it.title), s = norm(it.sub), k = norm(it.kw);
    if (!words.every(w => t.includes(w) || s.includes(w) || k.includes(w))) return;
    let score = 0;
    if (t.startsWith(n)) score += 100; else if (t.includes(n)) score += 60;
    words.forEach(w => { if (t.includes(w)) score += 10; else if (s.includes(w)) score += 4; else score += 1; });
    const at = t.indexOf(n) >= 0 ? t.indexOf(n) : t.indexOf(words[0]);
    const len = t.indexOf(n) >= 0 ? n.length : (t.indexOf(words[0]) >= 0 ? words[0].length : 0);
    out.push({ it, score, at, len });
  });
  return out.sort((a, b) => b.score - a.score);
}
